(2686654, 370320, 57384, '<td valign="top">Of all the drill BITS and the reese''s PIECES, this is the best shot, because it shows them together. Great creativity and a neat shot of the shell coming off.</td>', 'Of all the drill BITS and the reese''s PIECES, this is the best shot, because it shows them together. Great creativity and a neat shot of the shell coming off.', '2006-08-02 02:46:38.000000', NULL, 1),
(2686657, 371434, 57384, '<td valign="top">The dread of having to look through a box of junk. Great capture of something we all have to do. Love the light trail from the eye!</td>', 'The dread of having to look through a box of junk. Great capture of something we all have to do. Love the light trail from the eye!', '2006-08-02 02:47:24.000000', NULL, 1),
