(2687957, 373608, 61818, '<td valign="top">While it has holes in it, this still appears to be an intact flower with intact bugs crawling around on it.</td>', 'While it has holes in it, this still appears to be an intact flower with intact bugs crawling around on it.', '2006-08-02 11:05:58.000000', NULL, 1),
(2687968, 372713, 61818, '<td valign="top">The edge of the chess board being on an angle is very distracting.  I like the composition and I like how you''ve processed this to have that ''old'' look.  The jumble of pieces in the bottom left don''t work so well.  Might have been nicer to start with just the two cards even if you had to put a little tape on their backs to keep them there.  I think shooting this from a bit lower down towards the surface of the board might have played up some of the nice perspective here of the white and brown squares.<br/> <br/>Overall a good idea. 5.</td>', 'The edge of the chess board being on an angle is very distracting.  I like the composition and I like how you''ve processed this to have that ''old'' look.  The jumble of pieces in the bottom left don''t work so well.  Might have been nicer to start with just the two cards even if you had to put a little tape on their backs to keep them there.  I think shooting this from a bit lower down towards the surface of the board might have played up some of the nice perspective here of the white and brown squares. Overall a good idea. 5.', '2006-08-02 11:08:37.000000', NULL, 1),
(2687974, 373309, 61818, '<td valign="top">Seems like this could be a lot sharper.  I like the composition and the red background works well here.  Don''t care for the top of the golf ball being cropped off, might have been nice to get some of that red negative space wrapped completely aound the top of the image.  Also might be more interesting with the golf balls shifted over to the left.  Hmm.  Not a bad shot, it''s just not grabbing me. 5.</td>', 'Seems like this could be a lot sharper.  I like the composition and the red background works well here.  Don''t care for the top of the golf ball being cropped off, might have been nice to get some of that red negative space wrapped completely aound the top of the image.  Also might be more interesting with the golf balls shifted over to the left.  Hmm.  Not a bad shot, it''s just not grabbing me. 5.', '2006-08-02 11:10:13.000000', NULL, 1),
(2687981, 373399, 61818, '<td valign="top"><b>Piece</b> of an Orca... <b>Bit</b> of a stretch.</td>', 'Piece of an Orca... Bit of a stretch.', '2006-08-02 11:11:37.000000', NULL, 1),
(2687993, 373731, 61818, '<td valign="top">This is a really cool photo.  Very striking piece of eye candy.  Like how the hols in the objects make interesting shapes within the shapes.  The out of focus thing at the top is a bit distracting, but not too bad.  I just don''t see how it is pieces of anything or bits of anything.</td>', 'This is a really cool photo.  Very striking piece of eye candy.  Like how the hols in the objects make interesting shapes within the shapes.  The out of focus thing at the top is a bit distracting, but not too bad.  I just don''t see how it is pieces of anything or bits of anything.', '2006-08-02 11:14:25.000000', NULL, 1),
(2687998, 372641, 61818, '<td valign="top">Nice photo, meets the challenge (which was apparently no small feat this time).  I like BW photos a lot, but this one would benefit from a bit more contrast.  I would love to see those lines between the paving stones really jump out more and make an interesting pattern.  Overall, nice shot. 5.</td>', 'Nice photo, meets the challenge (which was apparently no small feat this time).  I like BW photos a lot, but this one would benefit from a bit more contrast.  I would love to see those lines between the paving stones really jump out more and make an interesting pattern.  Overall, nice shot. 5.', '2006-08-02 11:15:44.000000', NULL, 1),
(2688003, 371385, 61818, '<td valign="top">I like this shot.  The pipes pull the eye around and while it is a busy shot, it doesn''t overwhelm me to the point of distraction.  I don''t care for the border, but I find that I rarely see any benefit to a border being added.  Only thing I really would gripe about here is that jumble of wires in the lower right corner.  They have no place in this shot and are a bit of a distraction.  Nice work. 5.</td>', 'I like this shot.  The pipes pull the eye around and while it is a busy shot, it doesn''t overwhelm me to the point of distraction.  I don''t care for the border, but I find that I rarely see any benefit to a border being added.  Only thing I really would gripe about here is that jumble of wires in the lower right corner.  They have no place in this shot and are a bit of a distraction.  Nice work. 5.', '2006-08-02 11:19:15.000000', NULL, 1),
(2688010, 371925, 61818, '<td valign="top">Good idea for an entry.  Meets the challenge in a unique way.  There are some focus issues here, or something else, that isn''t quite right but I can''t think of how I would take a nice sharp picture of bubbles in gel so I''m afraid I can''t offer anything constructive.  Still, nice shot. 5.</td>', 'Good idea for an entry.  Meets the challenge in a unique way.  There are some focus issues here, or something else, that isn''t quite right but I can''t think of how I would take a nice sharp picture of bubbles in gel so I''m afraid I can''t offer anything constructive.  Still, nice shot. 5.', '2006-08-02 11:21:05.000000', NULL, 1),
(2688017, 372239, 61818, '<td valign="top">Nice idea and twist on the challenge theme.  The xray panel is off kilter which really detracts from this shot.  Colors are nice, even the mocked up heart is ok.  Would like to see the heart jump out a bit more, it''s a bit on the dark side.  OVerall, a nice piece of work. 5.</td>', 'Nice idea and twist on the challenge theme.  The xray panel is off kilter which really detracts from this shot.  Colors are nice, even the mocked up heart is ok.  Would like to see the heart jump out a bit more, it''s a bit on the dark side.  OVerall, a nice piece of work. 5.', '2006-08-02 11:22:46.000000', NULL, 1),
(2688020, 373340, 61818, '<td valign="top">Don''t care for the DOF, but this meets the challenge well and is an interesting composition. 5.</td>', 'Don''t care for the DOF, but this meets the challenge well and is an interesting composition. 5.', '2006-08-02 11:23:10.000000', NULL, 1),
(2688027, 373353, 61818, '<td valign="top">Meets the challenge well but a rather boring composition.  While the large weight could act as a focal point for this, the sheer volume of hooks and whatever the little pieces are overwhelm the shot to the point of distraction.  In part I think this is because of all the whitespace.  This might have been easier on the eyes if there were less whitespace and actually just a pile of hooks and the other stuff.  Then it would look more like a background to the large weight.  Nice shot overll. 4.</td>', 'Meets the challenge well but a rather boring composition.  While the large weight could act as a focal point for this, the sheer volume of hooks and whatever the little pieces are overwhelm the shot to the point of distraction.  In part I think this is because of all the whitespace.  This might have been easier on the eyes if there were less whitespace and actually just a pile of hooks and the other stuff.  Then it would look more like a background to the large weight.  Nice shot overll. 4.', '2006-08-02 11:25:26.000000', NULL, 1),
(2688030, 373711, 46371, '<td valign="top">I feel that way too.</td>', 'I feel that way too.', '2006-08-02 11:27:32.000000', NULL, 1),
(2688055, 371016, 61818, '<td valign="top">Not a bad idea and meets the challenge.  Would like to see the pieces in focus, it looks like maybe you focused on the light dot in the center instead.  Composition is a little rough.  Nice shot. 4.</td>', 'Not a bad idea and meets the challenge.  Would like to see the pieces in focus, it looks like maybe you focused on the light dot in the center instead.  Composition is a little rough.  Nice shot. 4.', '2006-08-02 11:35:08.000000', NULL, 1),
(2688061, 373439, 61818, '<td valign="top">Nice shot, meets the challenge.  I like how the composition is balanced.  Might have benefited from a slightly shallower DOF so the background cars are blurred out a bit, but that doesn''t ruin the shot for me.  Nice BW conversion though it is just a bit too much of the same shade of gray.  Possibly get a bit more radical with the channel mixer to give some additional contrast here.  Still, no one thing here is off to the point of blowing the shot.  Nice work. 6.</td>', 'Nice shot, meets the challenge.  I like how the composition is balanced.  Might have benefited from a slightly shallower DOF so the background cars are blurred out a bit, but that doesn''t ruin the shot for me.  Nice BW conversion though it is just a bit too much of the same shade of gray.  Possibly get a bit more radical with the channel mixer to give some additional contrast here.  Still, no one thing here is off to the point of blowing the shot.  Nice work. 6.', '2006-08-02 11:37:25.000000', NULL, 1),
(2688068, 373258, 24454, '<td valign="top">Cute set up  :)  I love those bold copper colors with blue!</td>', 'Cute set up  :)  I love those bold copper colors with blue!', '2006-08-02 11:40:38.000000', NULL, 1),
(2688071, 371444, 61818, '<td valign="top">Nice idea.  Personally, while I see your intent, I don''t think this meets the challenge very well.  Writing down a bunch of binary number sequences doesn''t constitue bits or pieces.  I''ll set that aside.  The photo itself - the way the paper is rolling up on the upper left side is very distracting.  Also the paper itself is on an angle.  Would work better if the text was perfectly horizontal.  The smudge within the magnifying glass is a distraction.  Also might have played with your white balance here, the whole shot has a greenish cast to it which doesn''t come across to well.  Might have tipped the glass back a bit too to better create the illusion that it is actually magnifying/decoding the paper beneath it.  Overall, nice idea. 5.</td>', 'Nice idea.  Personally, while I see your intent, I don''t think this meets the challenge very well.  Writing down a bunch of binary number sequences doesn''t constitue bits or pieces.  I''ll set that aside.  The photo itself - the way the paper is rolling up on the upper left side is very distracting.  Also the paper itself is on an angle.  Would work better if the text was perfectly horizontal.  The smudge within the magnifying glass is a distraction.  Also might have played with your white balance here, the whole shot has a greenish cast to it which doesn''t come across to well.  Might have tipped the glass back a bit too to better create the illusion that it is actually magnifying/decoding the paper beneath it.  Overall, nice idea. 5.', '2006-08-02 11:41:27.000000', NULL, 1),
(2688077, 373621, 61818, '<td valign="top">Nice idea and meets the challenge.  Looks like a lot of the paper is either overexposed or so out of focus that the detail has been lost.  Unfortunately it is to such an extent that the whole photo suffers greatly.  3.</td>', 'Nice idea and meets the challenge.  Looks like a lot of the paper is either overexposed or so out of focus that the detail has been lost.  Unfortunately it is to such an extent that the whole photo suffers greatly.  3.', '2006-08-02 11:43:54.000000', NULL, 1),
(2688078, 372965, 61818, '<td valign="top">Meets the challenge well.  Photo would work better if you got down on your knees and shot from a lower point of view.</td>', 'Meets the challenge well.  Photo would work better if you got down on your knees and shot from a lower point of view.', '2006-08-02 11:44:39.000000', NULL, 1),
(2688086, 373406, 63221, '<td valign="top">Bara að vera með ;)</td>', 'Bara að vera með ;)', '2006-08-02 11:48:13.000000', NULL, 1),
(2688087, 373256, 61818, '<td valign="top">Nice photo, meets the challenge well.  The lighting here sort of breaks the shot.  Would like to see the shards of glass better lit so they pop out more and grab the eye.  I like the dof leaving the carcass of the base of the bulb out of focus in the background.  The black background works very well here.  OVerall, a nice shot. 5.</td>', 'Nice photo, meets the challenge well.  The lighting here sort of breaks the shot.  Would like to see the shards of glass better lit so they pop out more and grab the eye.  I like the dof leaving the carcass of the base of the bulb out of focus in the background.  The black background works very well here.  OVerall, a nice shot. 5.', '2006-08-02 11:49:31.000000', NULL, 1),
(2688091, 372936, 51883, '<td valign="top">nice colours</td>', 'nice colours', '2006-08-02 11:51:19.000000', NULL, 1),
(2688093, 373341, 61818, '<td valign="top">Meets the challenge well.  The border is horrible.  The composition itself lacks any point of focus for the eyes.  This might have worked better if you limited the shot to just one wall, or maybe that shelf - something that would make the bits and pieces a little larger and give you opportunity to position one of them as a focal point of the shot.  Good work. 4.</td>', 'Meets the challenge well.  The border is horrible.  The composition itself lacks any point of focus for the eyes.  This might have worked better if you limited the shot to just one wall, or maybe that shelf - something that would make the bits and pieces a little larger and give you opportunity to position one of them as a focal point of the shot.  Good work. 4.', '2006-08-02 11:51:40.000000', NULL, 1),
(2688094, 372403, 24454, '<td valign="top">I''ve voted 19% of the images so far, and this is the first photo I''ve come to that I actually like!  I think the hodge-podge way you''ve photographed these zebras is just perfect for this challenge.  Thank you. . .I was just about to quit.   Now, maybe I can stand a few more  :)   Seriously. . .it''s a nice photo, and you did a really good job on it.</td>', 'I''ve voted 19% of the images so far, and this is the first photo I''ve come to that I actually like!  I think the hodge-podge way you''ve photographed these zebras is just perfect for this challenge.  Thank you. . .I was just about to quit.   Now, maybe I can stand a few more  :)   Seriously. . .it''s a nice photo, and you did a really good job on it.', '2006-08-02 11:51:42.000000', NULL, 1),
(2688100, 373687, 61818, '<td valign="top">Nice shot.  The border detracts from this picture.  Also do not care for the mirror and hand being partially cropped out of the shot.  The composition here is otherwise great and your focus is spot on.  Possibly a little more contrast to get the subjects to jump out a bit more from the background.  Nice work, 5.</td>', 'Nice shot.  The border detracts from this picture.  Also do not care for the mirror and hand being partially cropped out of the shot.  The composition here is otherwise great and your focus is spot on.  Possibly a little more contrast to get the subjects to jump out a bit more from the background.  Nice work, 5.', '2006-08-02 11:52:56.000000', NULL, 1),
(2688101, 373690, 62099, '<td valign="top">Over processed</td>', 'Over processed', '2006-08-02 11:53:06.000000', NULL, 1),
(2688102, 370588, 59029, '<td valign="top">aha a fellow horseperson!  Nice shot.  8</td>', 'aha a fellow horseperson!  Nice shot.  8', '2006-08-02 11:53:29.000000', NULL, 1),
(2688103, 373655, 24454, '<td valign="top">Very cute and well photographed!  This is one of the few images in this challenge that I''ve seen so far (after voting 21%) that is actually pleasing to look at!  Thank you for doing such a good job and submitting something worth voting on.   From what I''ve seen so far, this one should win blue.  Great job.</td>', 'Very cute and well photographed!  This is one of the few images in this challenge that I''ve seen so far (after voting 21%) that is actually pleasing to look at!  Thank you for doing such a good job and submitting something worth voting on.   From what I''ve seen so far, this one should win blue.  Great job.', '2006-08-02 11:53:54.000000', NULL, 1),
(2688104, 373519, 59029, '<td valign="top">Nice idea but blurry</td>', 'Nice idea but blurry', '2006-08-02 11:53:57.000000', NULL, 1),
(2688106, 373395, 59029, '<td valign="top">Oh YUM!</td>', 'Oh YUM!', '2006-08-02 11:54:34.000000', NULL, 1),
(2688107, 370501, 61818, '<td valign="top">Meets the challenge well.  Like the DOF a lot, perfect for this shot.  The angle you shot this at is great for these subjects.  No real complaint other than wishing the subjects jumped out a bit more from the background.  Either white balance needs to be adjusted a bit or this was shot on a gray background.  Gray subjects over the gray background sort of wash out the photo.  Otherwise, very nice.  6.</td>', 'Meets the challenge well.  Like the DOF a lot, perfect for this shot.  The angle you shot this at is great for these subjects.  No real complaint other than wishing the subjects jumped out a bit more from the background.  Either white balance needs to be adjusted a bit or this was shot on a gray background.  Gray subjects over the gray background sort of wash out the photo.  Otherwise, very nice.  6.', '2006-08-02 11:54:43.000000', NULL, 1),
(2688109, 373731, 24454, '<td valign="top">Ok. . .this one is very nice (one of the few here).  Abstract, awesome color, clean and crisp.  Kudos for having one of only about 3 or 4 here that aren''t horrible  :)   Hoping this one ribbons from what I''ve seen so far.  Great job!</td>', 'Ok. . .this one is very nice (one of the few here).  Abstract, awesome color, clean and crisp.  Kudos for having one of only about 3 or 4 here that aren''t horrible  :)   Hoping this one ribbons from what I''ve seen so far.  Great job!', '2006-08-02 11:55:53.000000', NULL, 1),
(2688110, 373687, 16241, '<td valign="top">great, different, love the black white</td>', 'great, different, love the black white', '2006-08-02 11:56:23.000000', NULL, 1),
(2688111, 370127, 59029, '<td valign="top">A little too much glare and OOF</td>', 'A little too much glare and OOF', '2006-08-02 11:57:45.000000', NULL, 1),
(2688113, 373013, 59029, '<td valign="top">So THATès where my old Hot Wheels went!</td>', 'So THATès where my old Hot Wheels went!', '2006-08-02 11:58:23.000000', NULL, 1),
(2688114, 373687, 24454, '<td valign="top">This is definitely a standout in this challenge!  The bold lines of the mirror stand add a lot to this image.  The composition is great, and it''s one of the few here that show creativity and good execution.  Great job.</td>', 'This is definitely a standout in this challenge!  The bold lines of the mirror stand add a lot to this image.  The composition is great, and it''s one of the few here that show creativity and good execution.  Great job.', '2006-08-02 11:58:31.000000', NULL, 1),
(2688115, 373711, 61818, '<td valign="top">Doesn''t meet the challenge.  You aren''t getting scored on your caption.  Also, I wouldn''t feel moved to ponder the political message you convey here when the artist can''t even spell Constitution.</td>', 'Doesn''t meet the challenge.  You aren''t getting scored on your caption.  Also, I wouldn''t feel moved to ponder the political message you convey here when the artist can''t even spell Constitution.', '2006-08-02 11:58:52.000000', NULL, 1),
(2688116, 370701, 24454, '<td valign="top">I like this one alot.  In fact, it may be my favorite so far.  The composition and contrast of that feather with the rocks and glass is very nice.  Good luck!</td>', 'I like this one alot.  In fact, it may be my favorite so far.  The composition and contrast of that feather with the rocks and glass is very nice.  Good luck!', '2006-08-02 11:59:26.000000', NULL, 1),
(2688119, 373655, 59029, '<td valign="top">Fun idea...but please donèt invite me to any cocktail parties at your place! ;-)</td>', 'Fun idea...but please donèt invite me to any cocktail parties at your place! ;-)', '2006-08-02 12:00:09.000000', NULL, 1),
(2688120, 373669, 59029, '<td valign="top">Nice saturation and comp</td>', 'Nice saturation and comp', '2006-08-02 12:00:34.000000', NULL, 1),
(2688124, 371480, 24454, '<td valign="top">This one is very nice!   It shows some creativity as well as an appealing composition!  Great job!!!</td>', 'This one is very nice!   It shows some creativity as well as an appealing composition!  Great job!!!', '2006-08-02 12:01:16.000000', NULL, 1),
(2688128, 372239, 59029, '<td valign="top">Wow, great shot, lots of imagination</td>', 'Wow, great shot, lots of imagination', '2006-08-02 12:02:28.000000', NULL, 1),
(2688130, 373720, 61818, '<td valign="top">Ok, meets the challenge.  I would suggest that you do not need to use your caption to spell out everything within the photo.  The lighting on this shot is good, though a little light from the front would have highlighted those nice colors better.  cOmposition is good and I like how it has been set on the black background. 5.</td>', 'Ok, meets the challenge.  I would suggest that you do not need to use your caption to spell out everything within the photo.  The lighting on this shot is good, though a little light from the front would have highlighted those nice colors better.  cOmposition is good and I like how it has been set on the black background. 5.', '2006-08-02 12:02:37.000000', NULL, 1),
(2688131, 373124, 61818, '<td valign="top">Meets the challenge well.  Very well done shot.  Good lighting, I like the highlights on the shards of glass.  Works very well in BW.  Great job. 7.</td>', 'Meets the challenge well.  Very well done shot.  Good lighting, I like the highlights on the shards of glass.  Works very well in BW.  Great job. 7.', '2006-08-02 12:03:15.000000', NULL, 1),
(2688133, 373279, 59029, '<td valign="top">A little cluttered but good</td>', 'A little cluttered but good', '2006-08-02 12:03:43.000000', NULL, 1),
(2688137, 373465, 63175, '<td valign="top">beautiful</td>', 'beautiful', '2006-08-02 12:04:51.000000', NULL, 1),
(2688138, 372262, 59029, '<td valign="top">I like the effect used on the water, but what is the red on the rocks</td>', 'I like the effect used on the water, but what is the red on the rocks', '2006-08-02 12:05:25.000000', NULL, 1),
(2688140, 371679, 59029, '<td valign="top">lovely</td>', 'lovely', '2006-08-02 12:05:41.000000', NULL, 1),
(2688142, 370900, 58305, '<td valign="top">What are they, dippin dots?</td>', 'What are they, dippin dots?', '2006-08-02 12:06:12.000000', NULL, 1),
(2688144, 372069, 59029, '<td valign="top">Very unusual but beautiful</td>', 'Very unusual but beautiful', '2006-08-02 12:06:51.000000', NULL, 1),
(2688146, 373096, 61818, '<td valign="top">I like this shot, but I think it would have worked much better against a black background.  The white background sort of washes this out and the reflections on the shards of mirror don''t have the ''pop'' that they could.  Overall, nice shot. 5.</td>', 'I like this shot, but I think it would have worked much better against a black background.  The white background sort of washes this out and the reflections on the shards of mirror don''t have the ''pop'' that they could.  Overall, nice shot. 5.', '2006-08-02 12:07:27.000000', NULL, 1),
(2688148, 373572, 38732, '<td valign="top">The lighting''s pretty flat giving this a very "snapshotty" appearance.  I do however like the play on words of your title.</td>', 'The lighting''s pretty flat giving this a very "snapshotty" appearance.  I do however like the play on words of your title.', '2006-08-02 12:07:35.000000', NULL, 1),
(2688149, 373361, 58305, '<td valign="top">What the hell does this have to do w/ "bits &amp; pieces"???</td>', 'What the hell does this have to do w/ "bits & pieces"???', '2006-08-02 12:08:17.000000', NULL, 1),
(2688150, 372994, 59029, '<td valign="top">Aha, another horseperson!</td>', 'Aha, another horseperson!', '2006-08-02 12:08:30.000000', NULL, 1),
(2688159, 373623, 58305, '<td valign="top">I love that book!!!Cool shot.</td>', 'I love that book!!!Cool shot.', '2006-08-02 12:12:08.000000', NULL, 1),
(2688163, 373402, 58305, '<td valign="top">Ummmmmmmmmmmmmmmmmmmmmm,kay.<br/>WTF???</td>', 'Ummmmmmmmmmmmmmmmmmmmmm,kay.WTF???', '2006-08-02 12:12:44.000000', NULL, 1),
(2688167, 373711, 58305, '<td valign="top">LOL, very clever.</td>', 'LOL, very clever.', '2006-08-02 12:13:58.000000', NULL, 1),
(2688169, 372192, 58305, '<td valign="top">BORING</td>', 'BORING', '2006-08-02 12:14:14.000000', NULL, 1),
(2688180, 372771, 61818, '<td valign="top">Think this one was basic editing?</td>', 'Think this one was basic editing?', '2006-08-02 12:19:19.000000', NULL, 1),
(2688211, 373650, 16402, '<td valign="top">Clever. DOF may be a bit too tight IMHO.</td>', 'Clever. DOF may be a bit too tight IMHO.', '2006-08-02 12:26:12.000000', NULL, 1),
(2688221, 372965, 16402, '<td valign="top">Wonder if a polorizing filter might have made this more interesting by cutting the reflection on the water.</td>', 'Wonder if a polorizing filter might have made this more interesting by cutting the reflection on the water.', '2006-08-02 12:30:24.000000', NULL, 1),
(2688263, 373752, 38732, '<td valign="top">Unfortunately, I find the lighting a bit of a problem.  There are some harsh shadows and blown highlights, particularly on and around the bird, which takes away much of its detail.  The photo may not be stellar, but the situation you''ve captured is somewhat emotional, and makes me wonder what happened to the bird.  I can see many people thinking that this doesn''t meet the challenge, but that doesn''t include me.</td>', 'Unfortunately, I find the lighting a bit of a problem.  There are some harsh shadows and blown highlights, particularly on and around the bird, which takes away much of its detail.  The photo may not be stellar, but the situation you''ve captured is somewhat emotional, and makes me wonder what happened to the bird.  I can see many people thinking that this doesn''t meet the challenge, but that doesn''t include me.', '2006-08-02 12:40:57.000000', NULL, 1),
(2688277, 372824, 38732, '<td valign="top">Lighting is very flat and much of the photo seems to be slightly out of focus, at least to me.</td>', 'Lighting is very flat and much of the photo seems to be slightly out of focus, at least to me.', '2006-08-02 12:43:10.000000', NULL, 1),
(2688303, 373529, 37525, '<td valign="top">Meets the challenge, however, poorly styled in my opinion</td>', 'Meets the challenge, however, poorly styled in my opinion', '2006-08-02 12:50:51.000000', NULL, 1),
(2688341, 373473, 58452, '<td valign="top">I think this is one where complexity adds, rather than subtracts.  Nice.</td>', 'I think this is one where complexity adds, rather than subtracts.  Nice.', '2006-08-02 12:59:49.000000', NULL, 1),
(2688348, 373500, 58452, '<td valign="top">I like the diagonal shadows.</td>', 'I like the diagonal shadows.', '2006-08-02 13:00:51.000000', NULL, 1),
(2688353, 373338, 57712, '<td valign="top">My initial thought was that it was a chaotic snapshot, but looking at it more I kinda like it. The wood frame makes a nice border. What I thought was chaotic makes for a feast of things to look at. It''s very nostalgic and every bit and piece tells a story.</td>', 'My initial thought was that it was a chaotic snapshot, but looking at it more I kinda like it. The wood frame makes a nice border. What I thought was chaotic makes for a feast of things to look at. It''s very nostalgic and every bit and piece tells a story.', '2006-08-02 13:01:22.000000', NULL, 1),
(2688357, 373731, 58452, '<td valign="top">I like the lines, lighting, and metallic look.<br/>Is it upside down?  ;)</td>', 'I like the lines, lighting, and metallic look.Is it upside down?  ;)', '2006-08-02 13:02:02.000000', NULL, 1),
(2688362, 372752, 58452, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2006-08-02 13:02:48.000000', NULL, 1),
(2688365, 373172, 57712, '<td valign="top">I like it, very abstract. It looks very space-like to me, or a blue version of Aliens!</td>', 'I like it, very abstract. It looks very space-like to me, or a blue version of Aliens!', '2006-08-02 13:02:59.000000', NULL, 1),
(2688366, 372165, 58452, '<td valign="top">Nice colors.</td>', 'Nice colors.', '2006-08-02 13:03:04.000000', NULL, 1),
(2688378, 373622, 37525, '<td valign="top">Perhaps a curved line would have been more interesting.  Just my opinion</td>', 'Perhaps a curved line would have been more interesting.  Just my opinion', '2006-08-02 13:05:04.000000', NULL, 1),
(2688381, 373340, 58452, '<td valign="top">Pale, understated colors with a compelling composition that I really like.  I just bumped it up a point thinking about it.  ;)</td>', 'Pale, understated colors with a compelling composition that I really like.  I just bumped it up a point thinking about it.  ;)', '2006-08-02 13:05:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2688388, 373726, 58452, '<td valign="top">Nice color contrasts.  Hadn''t seen the dice lately.  ;)</td>', 'Nice color contrasts.  Hadn''t seen the dice lately.  ;)', '2006-08-02 13:06:21.000000', NULL, 1),
(2688396, 373361, 58452, '<td valign="top">What kind of cat eats pastries?   Arrrgggghhhh.</td>', 'What kind of cat eats pastries?   Arrrgggghhhh.', '2006-08-02 13:07:58.000000', NULL, 1),
(2688422, 371089, 58452, '<td valign="top">Now that''s thinking outside of the box... er crate.<br/>Seems it was already drained before the fall.  ;)<br/>It''ll suck the life out of ya.</td>', 'Now that''s thinking outside of the box... er crate.Seems it was already drained before the fall.  ;)It''ll suck the life out of ya.', '2006-08-02 13:12:58.000000', NULL, 1),
(2688429, 372467, 45706, '<td valign="top">Nice idea, the flash seems to be a little harsh though; the detail on the body of the toaster suffered some loss. But I really like the idea, you might could have tried a different angle rather than a middle angle</td>', 'Nice idea, the flash seems to be a little harsh though; the detail on the body of the toaster suffered some loss. But I really like the idea, you might could have tried a different angle rather than a middle angle', '2006-08-02 13:15:26.000000', NULL, 1),
