(2694283, 373022, 55621, '<td valign="top">I hope the voters grasp the concept.  Excellent execution of this mountain.</td>', 'I hope the voters grasp the concept.  Excellent execution of this mountain.', '2006-08-04 03:06:02.000000', NULL, 1),
(2694341, 372917, 59058, '<td valign="top">:) Hilarious idea. Shadows seem a little too harsh ''tho.</td>', ':) Hilarious idea. Shadows seem a little too harsh ''tho.', '2006-08-04 04:02:27.000000', NULL, 1),
(2694344, 373672, 59058, '<td valign="top">Your title hints of the subject being ice, but I''m seeing more sky here than the bits and pieces of ice. Nonetheless, the play of patterns and shapes in this pic is interesting.</td>', 'Your title hints of the subject being ice, but I''m seeing more sky here than the bits and pieces of ice. Nonetheless, the play of patterns and shapes in this pic is interesting.', '2006-08-04 04:07:09.000000', NULL, 1),
(2694349, 373461, 59058, '<td valign="top">I like the strong message this picture tells. Love the details and sharpness especially the dirt and lines on the hand. On a side note, I''d like to see the background more blur.</td>', 'I like the strong message this picture tells. Love the details and sharpness especially the dirt and lines on the hand. On a side note, I''d like to see the background more blur.', '2006-08-04 04:11:43.000000', NULL, 1),
(2694351, 372806, 59058, '<td valign="top">Love the contrast, and the angle as well which sure makes one feel that the world is indeed round *LOL*</td>', 'Love the contrast, and the angle as well which sure makes one feel that the world is indeed round *LOL*', '2006-08-04 04:14:11.000000', NULL, 1),
(2694520, 373557, 17507, '<td valign="top">great use of color! you''d pick up an extra point or two from me if you had obsessively cleaned up the puzzle pieces to remove the fuzzy bits.</td>', 'great use of color! you''d pick up an extra point or two from me if you had obsessively cleaned up the puzzle pieces to remove the fuzzy bits.', '2006-08-04 04:58:26.000000', NULL, 1),
